import * as React from "react";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { X } from "lucide-react";
import { motion, AnimatePresence } from "motion/react";
import { cn } from "../lib/utils";
import type { GlassLevel } from "./card";

/**
 * Drawer / Sheet — slides in from any edge.
 *
 * Props:
 *   position  — "right" | "left" | "top" | "bottom" (default: "right")
 *   size      — "sm" (320px) | "md" (480px) | "lg" (720px) | "full" (default: "md")
 *   glass     — glass intensity on panel (default: false — solid bg)
 *   animated  — enable slide animation (default: true)
 *
 * Usage:
 *   <Drawer open={open} onOpenChange={setOpen}>
 *     <DrawerTrigger asChild><Button>Open</Button></DrawerTrigger>
 *     <DrawerContent position="right" size="lg">
 *       <DrawerHeader title="Edit" description="..." />
 *       <DrawerBody>...</DrawerBody>
 *       <DrawerFooter>...</DrawerFooter>
 *     </DrawerContent>
 *   </Drawer>
 */

const Drawer = DialogPrimitive.Root;
const DrawerTrigger = DialogPrimitive.Trigger;
const DrawerClose = DialogPrimitive.Close;

// ── Size tokens ──
const sizeClasses = {
  sm: "max-w-xs",    // 320px
  md: "max-w-md",    // 480px (~28rem)
  lg: "max-w-2xl",   // 720px (~42rem)
  full: "max-w-full",
} as const;

// Vertical drawer sizes (top/bottom)
const vSizeClasses = {
  sm: "max-h-[30vh]",
  md: "max-h-[50vh]",
  lg: "max-h-[75vh]",
  full: "max-h-screen",
} as const;

// ── Slide directions ──
type Position = "right" | "left" | "top" | "bottom";

const slideConfig: Record<Position, { initial: Record<string, number>; className: string }> = {
  right: { initial: { x: 300 }, className: "inset-y-0 right-0" },
  left: { initial: { x: -300 }, className: "inset-y-0 left-0" },
  top: { initial: { y: -300 }, className: "inset-x-0 top-0" },
  bottom: { initial: { y: 300 }, className: "inset-x-0 bottom-0" },
};

const isHorizontal = (p: Position) => p === "left" || p === "right";

// ── Overlay ──
const DrawerOverlay = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay ref={ref} asChild {...(props as any)}>
    <motion.div
      className={cn("fixed inset-0 z-50 bg-black/50 backdrop-blur-sm", className)}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    />
  </DialogPrimitive.Overlay>
));
DrawerOverlay.displayName = "DrawerOverlay";

// ── Content ──
export interface DrawerContentProps
  extends React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content> {
  /** Which edge to slide from. Default: "right". */
  position?: Position;
  /** Panel width/height. Default: "md". */
  size?: "sm" | "md" | "lg" | "full";
  /** Glass intensity. Default: false (solid). */
  glass?: GlassLevel | false;
  /** Enable slide animation. Default: true. */
  animated?: boolean;
}

const DrawerContent = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Content>,
  DrawerContentProps
>(
  (
    {
      className,
      children,
      position = "right",
      size = "md",
      glass = false,
      animated = true,
      ...props
    },
    ref,
  ) => {
    const { initial, className: posClass } = slideConfig[position];
    const horizontal = isHorizontal(position);

    const panelClasses = cn(
      "fixed z-50 flex flex-col shadow-xl",
      posClass,
      horizontal ? ["w-full", sizeClasses[size], "h-full"] : ["h-auto", vSizeClasses[size], "w-full"],
      glass
        ? [
            `bg-[var(--glass-card-bg-${glass})]`,
            `backdrop-blur-[var(--glass-blur-${glass})]`,
            "border border-[var(--glass-card-border)]",
          ]
        : "bg-card text-card-foreground border-l border-border",
      className,
    );

    const panel = (
      <DialogPrimitive.Content ref={ref} asChild {...(props as any)}>
        {animated ? (
          <motion.div
            className={panelClasses}
            initial={{ ...initial, opacity: 0 }}
            animate={{ x: 0, y: 0, opacity: 1 }}
            exit={{ ...initial, opacity: 0 }}
            transition={{ type: "spring", stiffness: 300, damping: 30 }}
          >
            {children}
          </motion.div>
        ) : (
          <div className={panelClasses}>{children}</div>
        )}
      </DialogPrimitive.Content>
    );

    return (
      <AnimatePresence>
        <DialogPrimitive.Portal forceMount>
          <DrawerOverlay />
          {panel}
        </DialogPrimitive.Portal>
      </AnimatePresence>
    );
  },
);
DrawerContent.displayName = "DrawerContent";

// ── Header ──
export interface DrawerHeaderProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title: React.ReactNode;
  description?: React.ReactNode;
}

const DrawerHeader: React.FC<DrawerHeaderProps> = ({
  title,
  description,
  className,
  children,
  ...props
}) => (
  <div
    className={cn(
      "flex items-start justify-between gap-4 px-6 py-4 border-b border-border shrink-0",
      className,
    )}
    {...(props as any)}
  >
    <div className="space-y-1 min-w-0">
      <DialogPrimitive.Title className="text-lg font-semibold leading-none tracking-tight">
        {title}
      </DialogPrimitive.Title>
      {description && (
        <DialogPrimitive.Description className="text-sm text-muted-foreground">
          {description}
        </DialogPrimitive.Description>
      )}
    </div>
    <DialogPrimitive.Close className="rounded-lg p-2 hover:bg-muted transition-colors shrink-0">
      <X className="h-4 w-4" />
      <span className="sr-only">Close</span>
    </DialogPrimitive.Close>
    {children}
  </div>
);
DrawerHeader.displayName = "DrawerHeader";

// ── Body (scrollable) ──
const DrawerBody = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    className={cn("flex-1 overflow-y-auto px-6 py-4", className)}
    {...(props as any)}
  />
));
DrawerBody.displayName = "DrawerBody";

// ── Footer ──
const DrawerFooter = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    className={cn(
      "flex items-center justify-end gap-2 px-6 py-4 border-t border-border shrink-0",
      className,
    )}
    {...(props as any)}
  />
));
DrawerFooter.displayName = "DrawerFooter";

export {
  Drawer,
  DrawerTrigger,
  DrawerClose,
  DrawerContent,
  DrawerOverlay,
  DrawerHeader,
  DrawerBody,
  DrawerFooter,
};
